mapper.select:
select from asset_test_case tc left join asset_link req on req.target_type = 'CASE' and req.target_id = tc.id and req.source_type = 'REQUIREMENT' and req.link_type = 'VERIFIES' and req.deleted_at is null left join asset_link api on api.source_type = 'API' and api.target_type = 'CASE' and api.target_id = tc.id and api.link_type = 'COVERS' and api.deleted_at is null
tc.project_id = #{projectId}
order by tc.created_at desc

mapper.insert:
insert into asset_test_case (
    id, project_id, code, title, description, source, source_ref, priority, status, tags, version,
    lifecycle_status, archived_at, deleted_at, created_at, updated_at
) values (
    #{id}, #{projectId}, #{code},
    #{title}, #{description}, #{source}, #{sourceRef}, #{priority}, #{status}, #{tags}, #{version},
    #{lifecycleStatus}, #{archivedAt}, #{deletedAt}, #{createdAt}, #{updatedAt}
)

mapper.select:
select count(*)
from asset_test_case
where project_id = #{projectId}
  and code = #{code}
  and id != #{excludeId}
  and deleted_at is null

